  for (const line of String(text).split(/\r?\n/)) {
    if (/^(`{3,}|~{3,})/.test(line)) { inCode = !inCode; continue; }
    if (inCode) continue;
    const trimmed = line.trimStart();
    if ((trimmed.startsWith('- ') || trimmed.startsWith('* ')) && trimmed.length > 2) {
      out.push(cleanInline(trimmed.slice(2)));
